//! Characters' equipped gear.
//!
//! Items are named by their client item index: the row in the inventory item map 80A5FFBE
//! (`data/items.json`, generated by tools/d1_item_table.py). A loadout (0x80801855, member 6
//! at +0x1E8) holds 20 equipped entries 0x8080183C {i64 item instance id, i16 item index,
//! ...}; the client caches each entry's gear (0x556C70 -> 0x5568C0) and skips index -1. The
//! peer character (family 0, 0x808017FD member 3) and the character summary (family 3,
//! 0x80801954 member 4) both carry one: that is what the game dresses a player in.

use crate::invest::Value;
use std::collections::HashMap;
use std::sync::OnceLock;

#[derive(serde::Deserialize, Clone)]
pub struct Item {
    pub index: i64,
    #[serde(default)]
    pub name: Option<String>,
    #[serde(default)]
    pub r#type: Option<String>,
    /// equipment slot code (definition +0x88): 2 primary, 3 special, 4 heavy, 6 subclass,
    /// 7 helmet, 8 gauntlets, 9 chest, 10 legs, 11 class item, 12 ship, 13 sparrow,
    /// 14 ghost, 25 emblem, 27 shader
    #[serde(default)]
    pub slot: Option<u8>,
    #[serde(default)]
    pub tier: Option<u8>,
    #[serde(default)]
    pub class: Option<String>,
    /// weapon sandbox pattern index (0x54C7F0 table), for weapons
    #[serde(default)]
    pub pattern: Option<i64>,
    /// investment stats from the definition: [stat index, value]
    #[serde(default)]
    pub stats: Vec<[i64; 2]>,
    /// default gear parts from the arrangement: [part key, gear index]
    #[serde(default)]
    pub gear: Vec<[i64; 2]>,
    /// the arrangement's other gear index (research)
    #[serde(default)]
    pub base: Option<i64>,
}

pub fn items() -> &'static [Item] {
    static T: OnceLock<Vec<Item>> = OnceLock::new();
    T.get_or_init(|| serde_json::from_str(include_str!("../data/items.json")).expect("items.json"))
}

fn by_name() -> &'static HashMap<String, Vec<usize>> {
    static M: OnceLock<HashMap<String, Vec<usize>>> = OnceLock::new();
    M.get_or_init(|| {
        let mut m: HashMap<String, Vec<usize>> = HashMap::new();
        for (i, it) in items().iter().enumerate() {
            if let Some(n) = &it.name {
                m.entry(n.to_lowercase()).or_default().push(i);
            }
        }
        m
    })
}

/// The item index for a name (first match, preferring one equippable by `class`).
pub fn find(name: &str, class: Option<&str>) -> Option<i64> {
    let rows = by_name().get(&name.trim().to_lowercase())?;
    let pick = rows
        .iter()
        .find(|&&i| items()[i].slot.is_some() && (class.is_none() || items()[i].class.is_none() || items()[i].class.as_deref() == class))
        .or_else(|| rows.first())?;
    Some(items()[*pick].index)
}

/// Class name for the character creation's class value (0x808017FC member 2).
pub fn class_name(class: i64) -> &'static str {
    match class {
        0 => "titan",
        1 => "hunter",
        _ => "warlock",
    }
}

/// The default kit per class, by item name.
fn default_kit(class: &str) -> Vec<&'static str> {
    let mut kit = vec![
        match class {
            "titan" => "Striker",
            "hunter" => "Gunslinger",
            _ => "Voidwalker",
        },
        "Fatebringer",
        "Praedyth's Revenge",
        "Gjallarhorn",
    ];
    // one exotic armor piece (the game allows one), the rest the Iron Banner set
    kit.extend(match class {
        "titan" => ["Helm of Saint-14", "Days of Iron Gauntlets", "Days of Iron Cuirass", "Days of Iron Greaves"],
        "hunter" => ["Celestial Nighthawk", "Days of Iron Grips", "Days of Iron Hauberk", "Days of Iron Boots"],
        _ => ["Obsidian Mind", "Days of Iron Gloves", "Days of Iron Raiment", "Days of Iron Steps"],
    });
    kit
}

/// Item indices to equip: D1B_LOADOUT=<name>;<name>;... overrides the default kit (names as in
/// data/items.json); slots the list leaves empty (class item, ghost, ship, sparrow, emblem,
/// shader) are filled with the first legendary of that slot for the class.
pub fn loadout(class: i64) -> Vec<i64> {
    let class = class_name(class);
    let names: Vec<String> = match std::env::var("D1B_LOADOUT") {
        Ok(v) if !v.trim().is_empty() => v.split(';').map(|s| s.to_string()).collect(),
        _ => default_kit(class).into_iter().map(String::from).collect(),
    };
    let mut out: Vec<i64> = Vec::new();
    let mut slots: Vec<u8> = Vec::new();
    for n in &names {
        match find(n, Some(class)) {
            Some(i) => {
                let it = &items()[i as usize];
                // one item per slot: a later name replaces an earlier one
                if let Some(s) = it.slot {
                    if let Some(p) = slots.iter().position(|&x| x == s) {
                        out[p] = i;
                        continue;
                    }
                    slots.push(s);
                } else {
                    slots.push(0);
                }
                out.push(i);
            }
            None => tracing::warn!("gear: no item named {n:?}"),
        }
    }
    // the sparrow (13) used to crash on summoning (0x7420F0) when items had no instances;
    // D1B_NO_SPARROW=1 leaves it out again
    let no_sparrow = std::env::var("D1B_NO_SPARROW").map(|v| v == "1").unwrap_or(false);
    for s in [6u8, 2, 3, 4, 7, 8, 9, 10, 11, 14, 12, 13, 25, 27] {
        if s == 13 && no_sparrow {
            continue;
        }
        if slots.contains(&s) {
            continue;
        }
        let fill = items()
            .iter()
            .filter(|it| it.slot == Some(s) && (it.class.is_none() || it.class.as_deref() == Some(class)))
            .max_by_key(|it| (it.tier.unwrap_or(0).min(4), std::cmp::Reverse(it.index)));
        if let Some(it) = fill {
            out.push(it.index);
            slots.push(s);
        }
    }
    out.truncate(20);
    out
}

/// Unequipped items carried in the character's buckets (the inventory screen and the
/// character screen's slot pickers): D1B_BACKPACK=<name>;<name>;... or a default set of
/// exotic weapons. Instance ids continue after the equipped ones (backpack_id).
pub fn backpack(class: i64) -> Vec<i64> {
    let class = class_name(class);
    let names: Vec<String> = match std::env::var("D1B_BACKPACK") {
        Ok(v) => v.split(';').map(|s| s.to_string()).filter(|s| !s.trim().is_empty()).collect(),
        _ => [
            "Thorn", "The Last Word", "Red Death", "Hawkmoon", "Ice Breaker", "Plan C", "Black Hammer",
            "Truth", "Thunderlord", "Super Good Advice",
        ]
        .iter()
        .map(|s| s.to_string())
        .collect(),
    };
    names
        .iter()
        .filter_map(|n| {
            let i = find(n, Some(class));
            if i.is_none() {
                tracing::warn!("gear: no item named {n:?}");
            }
            i
        })
        .collect()
}

/// Instance id of the character's k-th backpack item.
pub fn backpack_id(character: i64, k: usize) -> i64 {
    item_id(character, 0x100 + k)
}

/// Item objects for the backpack (same layout as item_values).
pub fn backpack_values(character: i64, items: &[i64]) -> Vec<(i64, Value)> {
    item_values(character, items)
        .into_iter()
        .enumerate()
        .map(|(k, (_, v))| {
            let id = backpack_id(character, k);
            let v = match v {
                Value::Struct(mut m) => {
                    m[0] = Some(Value::Int(id));
                    Value::Struct(m)
                }
                v => v,
            };
            (id, v)
        })
        .collect()
}

/// A loadout value (0x80801855) with these items equipped, in equipment slot order; each
/// entry names its inventory item (item_id, item_values).
pub fn loadout_value(character: i64, items: &[i64]) -> Value {
    use Value::*;
    // entry p is equipment slot p (EQUIPMENT_SLOTS): the player configuration (0x912240)
    // reads the subclass, weapons, ... at fixed entries
    let mut slot: Vec<(i64, i64)> = vec![(0, -1); 20];
    for (k, &index) in items.iter().enumerate() {
        if let Some(code) = crate::gear::items().get(index as usize).and_then(|it| it.slot) {
            if let Some(p) = EQUIPMENT_SLOTS.iter().position(|&s| s == code) {
                slot[p] = (item_id(character, k), index);
            }
        }
    }
    let entries: Vec<Option<Value>> = slot
        .into_iter()
        // {i64 instance, i16 item index @8, i16 weapon sandbox pattern index @0xA (0x910C60 takes
        // the weapon's gear from the 0x54C7F0 pattern table; 0 elsewhere), i16 base gear @0xC}
        .map(|(id, index)| {
            let item = crate::gear::items().get(index.max(0) as usize).filter(|_| index >= 0);
            let pattern = item.and_then(|it| it.pattern).unwrap_or(0);
            // member 3 (@0xC): the item's base gear index (0x54C5B0 table: the definition
            // arrangement's base). 0x54DFF0 resolves its parts (weapon / armor models) from it into
            // the player's per-slot part handles (player record +0x9C8); member 4 (@0xE, 7 x
            // i16) would override single parts with other indices of the same table
            let base = item.and_then(|it| it.base).unwrap_or(0);
            let mut e = vec![Some(Int(id)), Some(Int(index)), Some(Int(pattern)), Some(Int(base)), None, None, None];
            // member 6 (@0x28, 0x808046BC): the gear parts {i8 key, i16 gear index}; the
            // weapon config (0x9109B0) looks up parts 5-7 here for the weapon's gear request
            if let Some(it) = item.filter(|it| !it.gear.is_empty()) {
                let parts: &[[i64; 2]] = &it.gear;
                e[6] = Some(Array(parts.iter().take(6).map(|[k, g]| Some(Struct(vec![Some(Int(*k)), Some(Int(*g))]))).collect()));
            }
            Some(Struct(e))
        })
        .collect();
    let mut m = vec![None; 16];
    m[6] = Some(Array(entries));
    // members 13-15 (0x80804703 at +0x888 / +0x908 / +0x988: 16 x {i8 stat index, i32 value},
    // -1 = unused): the primary, special and heavy weapon's stats. The character data keeps
    // them at +0x14E0 / +0x1560 / +0x15E0 (loadout + 0xC58, like the perk lists, members 9-11
    // -> +0x1400) and the player configuration (0x910C60) turns them into the weapon's
    // numbers (magazine, reserve ammo, ...). Traced with D1_TRACE_GEAR: the weapon configs'
    // stat slots carry these values. Member 12 (+0x808) is another list, left empty.
    for (member, code) in [(13usize, 2u8), (14, 3), (15, 4)] {
        let stats = items
            .iter()
            .filter_map(|&i| crate::gear::items().get(i as usize))
            .find(|it| it.slot == Some(code))
            .map(|it| it.stats.clone())
            .unwrap_or_default();
        let mut list: Vec<Option<Value>> = stats
            .iter()
            .take(16)
            .map(|[k, v]| Some(Struct(vec![Some(Int(*k)), Some(Int(*v))])))
            .collect();
        list.resize(16, Some(Struct(vec![Some(Int(-1)), Some(Int(0))])));
        m[member] = Some(Array(list));
    }
    Struct(m)
}

/// Inventory item 0x80801732 (family 4 slot 3): {i64 instance id, {i64 owner character, i2
/// location}, {i32 quantity, i32, i16}, i16 item index @+0x24, ...}. The game finds a
/// loadout entry's item through its instance id (0x56DC00).
pub const TYPE_ITEM: &str = "0x80801732";

/// Instance id of the character's k-th equipped item.
pub fn item_id(character: i64, k: usize) -> i64 {
    character.wrapping_add(0x1_0000 + k as i64)
}

/// The item objects for a character's equipped items (instance ids from item_id). Location:
/// D1B_ITEM_LOCATION (research; default 1).
pub fn item_values(character: i64, items: &[i64]) -> Vec<(i64, Value)> {
    use Value::*;
    let location = std::env::var("D1B_ITEM_LOCATION").ok().and_then(|v| v.parse().ok()).unwrap_or(1i64);
    items
        .iter()
        .enumerate()
        .map(|(k, &index)| {
            let id = item_id(character, k);
            let mut m = vec![None; 8];
            m[0] = Some(Int(id));
            m[1] = Some(Struct(vec![Some(Int(character)), Some(Int(location))]));
            m[2] = Some(Struct(vec![Some(Int(1)), Some(Int(0)), Some(Int(0))]));
            m[3] = Some(Int(index));
            // member 5 (@0x38, 0x80801846) instance data, member 0 the primary stat
            // 0x8080176B {i32 stat index, i32 value, i32 max, i16} (research: the character's
            // Light is the average of the equipped items' primary stats; attack is stat 11 on
            // weapons, defense stat 1 on armour: the definition's first stat, valued 0 there)
            if let Some((stat, value)) = primary_stat(index) {
                m[5] = Some(Struct(vec![Some(Struct(vec![Some(Int(stat)), Some(Int(value)), Some(Int(value))]))]));
            }
            (id, Struct(m))
        })
        .collect()
}

/// An item's primary stat: (stat index, value). D1B_ITEM_LIGHT (default 400) for weapons and
/// armour; none for other items.
fn primary_stat(index: i64) -> Option<(i64, i64)> {
    let it = items().get(index.max(0) as usize)?;
    let light = std::env::var("D1B_ITEM_LIGHT").ok().and_then(|v| v.parse().ok()).unwrap_or(400i64);
    let stat = match it.stats.first() {
        Some([k, _]) => *k,
        None => match it.slot? {
            2..=4 => 11,
            7..=11 | 14 | 36 => 1,
            _ => return None,
        },
    };
    match it.slot? {
        2..=4 | 7..=11 | 14 | 36 => Some((stat, light)),
        _ => None,
    }
}

/// Equipment slot order (definitions manager vtable +0x100: 17 rows {bucket hash, item slot
/// code @+5}): subclass, helmet, gauntlets, chest, legs, class item, primary, special, heavy,
/// ship, sparrow, ghost, emblem, shader, emote, horn, artifact.
pub const EQUIPMENT_SLOTS: [u8; 17] = [6, 7, 8, 9, 10, 11, 2, 3, 4, 12, 13, 14, 25, 27, 28, 30, 36];

/// The active character's equipped item ids (0x80801714 member 5 at +0x2B80, 0x808045DA:
/// 20 x i64 in equipment slot order; iterated by c_investment_character_equipment_const_iterator
/// 0x269230, which resolves each id to its inventory item).
pub fn equipment_value(character: i64, items: &[i64]) -> Value {
    use Value::*;
    let mut ids = vec![0i64; 20];
    for (k, &index) in items.iter().enumerate() {
        if let Some(code) = crate::gear::items().get(index as usize).and_then(|it| it.slot) {
            if let Some(p) = EQUIPMENT_SLOTS.iter().position(|&s| s == code) {
                ids[p] = item_id(character, k);
            }
        }
    }
    Array(ids.into_iter().map(|i| Some(Int(i))).collect())
}

/// The active character's inventory (0x80801714 member 3 at +0x30, 0x80800F9F): {i32 count,
/// 340 x 0x808016E0 {i16 item index, i64 instance id, i32, i32, i32}}. This is the list the
/// game treats as "items the character has": the world tag loader's character-instance
/// filler (0x576410 -> 0x554B90) walks it from +0x38 and loads each item's gear
/// (0x5551A0 with the definition's +0x58 index), checking equipped ones against the
/// equipment (0x269750). Without it the in-world weapons, the ship and the item slots have
/// nothing loaded. The three i32 are not known yet and are left out.
pub fn inventory_value(character: i64, equipped: &[i64], backpack: &[i64]) -> Value {
    use Value::*;
    let mut entries: Vec<Option<Value>> = Vec::new();
    for (k, &index) in equipped.iter().enumerate() {
        entries.push(Some(Struct(vec![Some(Int(index)), Some(Int(item_id(character, k)))])));
    }
    for (k, &index) in backpack.iter().enumerate() {
        entries.push(Some(Struct(vec![Some(Int(index)), Some(Int(backpack_id(character, k)))])));
    }
    let n = entries.len() as i64;
    Struct(vec![Some(Int(n)), Some(Array(entries))])
}

